<?php
declare(strict_types=1);
require_once __DIR__ . '/../config/db.php';
header('Content-Type: text/html; charset=utf-8');
require_once __DIR__ . '/common.php';
$ownerId = payment_require_owner();
$stmt = $conn->prepare("SELECT i.id,i.amount,i.generated_on,COALESCE(i.payment_status,'pending') AS payment_status,b.id AS booking_id,b.slot_datetime,v.reg_number,v.make,v.model FROM invoices i JOIN bookings b ON b.id=i.booking_id JOIN vehicles v ON v.id=b.vehicle_id WHERE b.owner_id=? ORDER BY i.generated_on DESC");
$stmt->bind_param('i',$ownerId); $stmt->execute(); $rows=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AutoCare Invoices</title><style>body{font:16px system-ui;background:#f3f6fb;color:#172033;margin:0}.wrap{max-width:980px;margin:5vh auto;padding:18px}.card{background:white;border-radius:16px;padding:24px;box-shadow:0 12px 40px #14213d14;overflow:auto}table{width:100%;border-collapse:collapse;margin-top:18px}th,td{text-align:left;padding:13px;border-bottom:1px solid #e5eaf2}.btn{display:inline-block;padding:8px 12px;border-radius:8px;background:#155eef;color:white;text-decoration:none;font-weight:650}.paid{color:#067647;font-weight:700}.pending{color:#b54708;font-weight:700}.muted{color:#667085}</style></head><body><main class="wrap"><section class="card"><h1>Your AutoCare Invoices</h1><p class="muted">Signed in as <?= h($_SESSION['user']['name'] ?? 'Owner') ?>. Payments are available only for invoices belonging to your account.</p><?php if(!$rows): ?><p>No database invoices found for your account. Create a booking and invoice in the database first.</p><?php else: ?><table><thead><tr><th>Invoice</th><th>Vehicle</th><th>Booking date</th><th>Amount</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td>#<?= (int)$r['id'] ?></td><td><?= h(trim(($r['make']??'').' '.($r['model']??''))) ?> <small><?= h($r['reg_number']) ?></small></td><td><?= h($r['slot_datetime']) ?></td><td>₹<?= number_format((float)$r['amount'],2) ?></td><td class="<?= $r['payment_status']==='paid'?'paid':'pending' ?>"><?= h(ucfirst($r['payment_status'])) ?></td><td><?php if($r['payment_status']==='paid'): ?><span class="paid">Paid</span><?php else: ?><a class="btn" href="checkout.php?invoice_id=<?= (int)$r['id'] ?>">Pay now</a><?php endif; ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></section></main></body></html>
